-- MacroLift core schema.
--
-- Conventions
--   * UUID primary keys, generated by the client where idempotent retries matter.
--   * Every personal row carries user_id -> auth.users ON DELETE CASCADE, so deleting the
--     auth user deletes all of that person's data (see delete_my_account()).
--   * Child rows also carry user_id and use a composite FK (parent_id, user_id) so a child can
--     never point at a parent owned by someone else, independent of RLS.
--   * Body values are stored canonically in kg / cm; conversion happens in the app.
--   * NULL nutrient values mean "unknown", never zero.
--   * Every numeric column has an upper bound, which also rejects NaN and Infinity
--     (both sort above every finite numeric in PostgreSQL).
--   * History tables (workout sessions, diary entries) keep snapshots so later edits to
--     exercises, routines or foods never rewrite the past.

-- ---------------------------------------------------------------------------
-- Types
-- ---------------------------------------------------------------------------

create type public.unit_system as enum ('metric', 'imperial');

-- Only used for the Mifflin-St Jeor coefficient. Never inferred.
create type public.estimate_sex as enum ('male', 'female');

create type public.activity_level as enum (
  'sedentary', 'lightly_active', 'moderately_active', 'very_active', 'extra_active'
);

create type public.muscle_group as enum (
  'chest', 'upper_back', 'lats', 'lower_back', 'traps', 'shoulders', 'biceps', 'triceps',
  'forearms', 'abs', 'obliques', 'quads', 'hamstrings', 'glutes', 'calves', 'adductors',
  'abductors', 'neck', 'full_body', 'cardio'
);

create type public.equipment_type as enum (
  'barbell', 'dumbbell', 'machine', 'cable', 'bodyweight', 'kettlebell', 'band',
  'smith_machine', 'ez_bar', 'trap_bar', 'other'
);

-- How a set's weight should be interpreted. Volume is only computed for 'external'.
--   external   : weight_kg is the load lifted (barbell, dumbbell, machine ...)
--   bodyweight : weight_kg, if present, is load added to body weight
--   assisted   : weight_kg, if present, is assistance (counterweight) subtracted
create type public.load_type as enum ('external', 'bodyweight', 'assisted');

create type public.workout_status as enum ('in_progress', 'completed');

create type public.meal_category as enum ('breakfast', 'lunch', 'dinner', 'snack');

create type public.measurement_site as enum (
  'neck', 'shoulders', 'chest', 'waist', 'hips', 'left_arm', 'right_arm', 'left_forearm',
  'right_forearm', 'left_thigh', 'right_thigh', 'left_calf', 'right_calf'
);

-- ---------------------------------------------------------------------------
-- Trigger helpers
-- ---------------------------------------------------------------------------

create function public.set_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- Monotonic revision used by the client to detect conflicting edits on reconnect.
create function public.bump_revision() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.revision := old.revision + 1;
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Profiles & preferences
-- ---------------------------------------------------------------------------

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text check (char_length(display_name) between 1 and 80),
  unit_system public.unit_system not null default 'metric',
  -- Optional inputs for the maintenance estimate. All nullable; the user may skip.
  birth_date date check (birth_date >= date '1900-01-01'),
  height_cm numeric check (height_cm > 0 and height_cm < 300),
  estimate_sex public.estimate_sex,
  activity_level public.activity_level,
  onboarding_completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create function public.validate_profile() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.birth_date is not null and new.birth_date > current_date then
    raise exception 'birth_date cannot be in the future' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger profiles_validate before insert or update on public.profiles
  for each row execute function public.validate_profile();
create trigger profiles_updated_at before update on public.profiles
  for each row execute function public.set_updated_at();

-- Create a profile row for every new auth user (email/password or Google).
create function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id) values (new.id) on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Nutrition targets (user-entered, effective-dated). The target for day D is the row with
-- the greatest effective_from <= D. Never written by the maintenance estimate.
-- ---------------------------------------------------------------------------

create table public.nutrition_targets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  effective_from date not null check (effective_from between date '1900-01-01' and date '2200-01-01'),
  calories_kcal numeric check (calories_kcal > 0 and calories_kcal <= 20000),
  protein_g numeric check (protein_g >= 0 and protein_g <= 2000),
  carbs_g numeric check (carbs_g >= 0 and carbs_g <= 5000),
  fat_g numeric check (fat_g >= 0 and fat_g <= 2000),
  fiber_g numeric check (fiber_g >= 0 and fiber_g <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, effective_from)
);

create trigger nutrition_targets_updated_at before update on public.nutrition_targets
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Exercise catalog: owner_id NULL = built-in (read-only), otherwise user-owned.
-- ---------------------------------------------------------------------------

create table public.exercises (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references auth.users (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 100),
  muscles public.muscle_group[] not null default '{}'
    check (cardinality(muscles) <= 10),
  equipment public.equipment_type,
  load_type public.load_type not null default 'external',
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index exercises_builtin_name_key on public.exercises (lower(name))
  where owner_id is null;
create unique index exercises_owner_name_key on public.exercises (owner_id, lower(name))
  where owner_id is not null and archived_at is null;
create index exercises_owner_idx on public.exercises (owner_id);

create trigger exercises_updated_at before update on public.exercises
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Routines
-- ---------------------------------------------------------------------------

create table public.routines (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 100),
  notes text check (char_length(notes) <= 2000),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id)
);

create index routines_user_idx on public.routines (user_id);
create trigger routines_updated_at before update on public.routines
  for each row execute function public.set_updated_at();

create table public.routine_exercises (
  id uuid primary key default gen_random_uuid(),
  routine_id uuid not null,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  exercise_id uuid not null references public.exercises (id),
  position integer not null check (position between 0 and 1000),
  -- Optional targets. NULL means "no target", never zero.
  target_sets integer check (target_sets between 1 and 50),
  target_reps_min integer check (target_reps_min between 1 and 1000),
  target_reps_max integer check (target_reps_max between 1 and 1000),
  notes text check (char_length(notes) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (routine_id, user_id) references public.routines (id, user_id) on delete cascade,
  check (target_reps_min is null or target_reps_max is null or target_reps_min <= target_reps_max)
);

create index routine_exercises_routine_idx on public.routine_exercises (routine_id, position);
create index routine_exercises_user_idx on public.routine_exercises (user_id);
create index routine_exercises_exercise_idx on public.routine_exercises (exercise_id);
create trigger routine_exercises_updated_at before update on public.routine_exercises
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Workout sessions (history). Snapshots keep names/load types as they were at log time.
-- ---------------------------------------------------------------------------

create table public.workout_sessions (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  routine_id uuid references public.routines (id) on delete set null,
  routine_name_snapshot text check (char_length(routine_name_snapshot) <= 100),
  name text check (char_length(name) <= 100),
  status public.workout_status not null default 'in_progress',
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  notes text check (char_length(notes) <= 4000),
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  check ((status = 'completed') = (completed_at is not null)),
  check (completed_at is null or completed_at >= started_at)
);

-- At most one active workout per user, which makes "resume" unambiguous.
create unique index workout_sessions_one_active on public.workout_sessions (user_id)
  where status = 'in_progress';
create index workout_sessions_user_started_idx on public.workout_sessions (user_id, started_at desc);
create index workout_sessions_routine_idx on public.workout_sessions (routine_id);
create trigger workout_sessions_revision before update on public.workout_sessions
  for each row execute function public.bump_revision();

create table public.session_exercises (
  id uuid primary key,
  session_id uuid not null,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  exercise_id uuid references public.exercises (id) on delete set null,
  exercise_name_snapshot text not null check (char_length(btrim(exercise_name_snapshot)) between 1 and 100),
  load_type_snapshot public.load_type not null default 'external',
  position integer not null check (position between 0 and 1000),
  notes text check (char_length(notes) <= 2000),
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (session_id, user_id) references public.workout_sessions (id, user_id) on delete cascade
);

create index session_exercises_session_idx on public.session_exercises (session_id, position);
create index session_exercises_user_idx on public.session_exercises (user_id);
create index session_exercises_exercise_idx on public.session_exercises (exercise_id);
create trigger session_exercises_revision before update on public.session_exercises
  for each row execute function public.bump_revision();

create table public.workout_sets (
  id uuid primary key,
  session_exercise_id uuid not null,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  position integer not null check (position between 0 and 1000),
  -- Blank stays NULL; it is never coerced to zero.
  reps integer check (reps between 0 and 10000),
  weight_kg numeric check (weight_kg >= 0 and weight_kg < 2000),
  is_warmup boolean not null default false,
  completed boolean not null default false,
  notes text check (char_length(notes) <= 1000),
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (session_exercise_id, user_id)
    references public.session_exercises (id, user_id) on delete cascade
);

create index workout_sets_parent_idx on public.workout_sets (session_exercise_id, position);
create index workout_sets_user_idx on public.workout_sets (user_id);
create trigger workout_sets_revision before update on public.workout_sets
  for each row execute function public.bump_revision();

-- ---------------------------------------------------------------------------
-- Body tracking (kg / cm). One weigh-in and one value per site per day; re-saving a day
-- updates it.
-- ---------------------------------------------------------------------------

create table public.weight_entries (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  measured_on date not null check (measured_on between date '1900-01-01' and date '2200-01-01'),
  weight_kg numeric not null check (weight_kg > 0 and weight_kg < 1000),
  note text check (char_length(note) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, measured_on)
);

create index weight_entries_user_date_idx on public.weight_entries (user_id, measured_on desc);
create trigger weight_entries_updated_at before update on public.weight_entries
  for each row execute function public.set_updated_at();

create table public.body_measurements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  measured_on date not null check (measured_on between date '1900-01-01' and date '2200-01-01'),
  site public.measurement_site not null,
  value_cm numeric not null check (value_cm > 0 and value_cm < 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, measured_on, site)
);

create index body_measurements_user_date_idx on public.body_measurements (user_id, measured_on desc);
create trigger body_measurements_updated_at before update on public.body_measurements
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Foods: owner_id NULL = built-in (read-only). Nutrients are per serving; NULL = unknown.
-- ---------------------------------------------------------------------------

create table public.foods (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references auth.users (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 120),
  brand text check (char_length(brand) <= 120),
  serving_size numeric not null check (serving_size > 0 and serving_size <= 100000),
  serving_unit text not null check (char_length(btrim(serving_unit)) between 1 and 30),
  calories_kcal numeric check (calories_kcal >= 0 and calories_kcal <= 100000),
  protein_g numeric check (protein_g >= 0 and protein_g <= 10000),
  carbs_g numeric check (carbs_g >= 0 and carbs_g <= 10000),
  fat_g numeric check (fat_g >= 0 and fat_g <= 10000),
  fiber_g numeric check (fiber_g >= 0 and fiber_g <= 10000),
  sugar_g numeric check (sugar_g >= 0 and sugar_g <= 10000),
  sodium_mg numeric check (sodium_mg >= 0 and sodium_mg <= 1000000),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index foods_owner_idx on public.foods (owner_id);
create trigger foods_updated_at before update on public.foods
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Meal templates (reusable meals). Items reference live foods; logging a template copies
-- each item into diary_entries as snapshots.
-- ---------------------------------------------------------------------------

create table public.meal_templates (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 100),
  notes text check (char_length(notes) <= 1000),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id)
);

create index meal_templates_user_idx on public.meal_templates (user_id);
create trigger meal_templates_updated_at before update on public.meal_templates
  for each row execute function public.set_updated_at();

create table public.meal_template_items (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  food_id uuid not null references public.foods (id),
  position integer not null check (position between 0 and 1000),
  quantity numeric not null check (quantity > 0 and quantity <= 10000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (template_id, user_id) references public.meal_templates (id, user_id) on delete cascade
);

create index meal_template_items_template_idx on public.meal_template_items (template_id, position);
create index meal_template_items_user_idx on public.meal_template_items (user_id);
create index meal_template_items_food_idx on public.meal_template_items (food_id);
create trigger meal_template_items_updated_at before update on public.meal_template_items
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Nutrition diary
-- ---------------------------------------------------------------------------

create table public.nutrition_days (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  day date not null check (day between date '1900-01-01' and date '2200-01-01'),
  notes text check (char_length(notes) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, day),
  unique (id, user_id)
);

create trigger nutrition_days_updated_at before update on public.nutrition_days
  for each row execute function public.set_updated_at();

create table public.diary_entries (
  id uuid primary key,
  nutrition_day_id uuid not null,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  meal public.meal_category not null,
  position integer not null default 0 check (position between 0 and 1000),
  -- Provenance only; the snapshot below is authoritative for history.
  food_id uuid references public.foods (id) on delete set null,
  meal_template_id uuid references public.meal_templates (id) on delete set null,
  -- Snapshot of the food at log time (per serving). NULL nutrient = unknown.
  food_name text not null check (char_length(btrim(food_name)) between 1 and 120),
  brand text check (char_length(brand) <= 120),
  serving_size numeric not null check (serving_size > 0 and serving_size <= 100000),
  serving_unit text not null check (char_length(btrim(serving_unit)) between 1 and 30),
  calories_kcal numeric check (calories_kcal >= 0 and calories_kcal <= 100000),
  protein_g numeric check (protein_g >= 0 and protein_g <= 10000),
  carbs_g numeric check (carbs_g >= 0 and carbs_g <= 10000),
  fat_g numeric check (fat_g >= 0 and fat_g <= 10000),
  fiber_g numeric check (fiber_g >= 0 and fiber_g <= 10000),
  sugar_g numeric check (sugar_g >= 0 and sugar_g <= 10000),
  sodium_mg numeric check (sodium_mg >= 0 and sodium_mg <= 1000000),
  -- Number of servings eaten.
  quantity numeric not null check (quantity > 0 and quantity <= 10000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (nutrition_day_id, user_id)
    references public.nutrition_days (id, user_id) on delete cascade
);

create index diary_entries_day_idx on public.diary_entries (nutrition_day_id, meal, position);
create index diary_entries_user_idx on public.diary_entries (user_id);
create index diary_entries_food_idx on public.diary_entries (food_id);
create index diary_entries_template_idx on public.diary_entries (meal_template_id);
create trigger diary_entries_updated_at before update on public.diary_entries
  for each row execute function public.set_updated_at();
